default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Group Policy\{827D319E-6EAC-11D2-A4EA-00C04F79F83A}' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('NoGPOListChanges', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]0)) {
    Write-Output 'Mismatch: HKLM:\SOFTWARE\Policies\Microsoft\Windows\Group Policy\{827D319E-6EAC-11D2-A4EA-00C04F79F83A} [NoGPOListChanges]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Group Policy\{827D319E-6EAC-11D2-A4EA-00C04F79F83A}')) {
    New-Item -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Group Policy\{827D319E-6EAC-11D2-A4EA-00C04F79F83A}' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Group Policy\{827D319E-6EAC-11D2-A4EA-00C04F79F83A}' -Name 'NoGPOListChanges' -Value 0 -PropertyType DWord -Force | Out-Null
exit 0
